import numpy as np, torch, model
net=model.load(); neg=model.negatives()
uid=list(neg['uid']); NC=np.asarray(neg['c']); NA=np.asarray(neg['a'])
np.random.seed(2); M=768
xs=np.random.randn(M,2).astype(np.float32)
grid=np.round(np.arange(0.0,1.0001,0.025),3)
outs={c:np.asarray(model.decode(net,xs,np.full(M,c,np.float32))) for c in grid}
def track(c0,a0):
    ctr={}
    def follow(order,p):
        p=p.copy()
        for c in order:
            a=outs[c]
            for _ in range(3):
                m=np.linalg.norm(a-p,axis=1)<0.6
                if m.sum()<5: break
                p=a[m].mean(0)
            ctr[c]=p.copy()
    cs=grid[np.argmin(np.abs(grid-c0))]; i0=list(grid).index(cs)
    follow(grid[i0:],a0); follow(grid[:i0+1][::-1],a0)
    return np.array([ctr[c] for c in grid])
others=[i for i,u in enumerate(uid) if u not in (8,13,29)]
OT=[track(NC[i],NA[i]) for i in others]
T=np.load('track.npy')
def near(a,c,tr):
    cx=np.interp(c,grid,tr[:,0]); cy=np.interp(c,grid,tr[:,1]); return np.hypot(a[:,0]-cx,a[:,1]-cy)<0.6
def lab(a,c): return near(a,c,T[:,1:3])
def olab(a,c):
    m=np.zeros(len(a),bool)
    for tr in OT: m|=near(a,c,tr)
    return m
