import numpy as np, torch, model
np.set_printoptions(precision=3, suppress=True, linewidth=160)
net=model.load()
w=torch.tensor(np.load('contrast_c0_blocks.1_k10.npy')); b=-12.9014
c=torch.tensor(np.load('sim_c.npy'))[:4096]; xi=torch.tensor(np.load('sim_xi.npy'))[:4096]; a0=np.load('sim_a.npy')[:4096]
cn=c.numpy()
def tgt(a):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); r=np.linalg.norm(a,axis=1)
    return (np.abs(ang-(5+58*cn))<9)&(r>2)
T0=tgt(a0); print('target share',T0.mean())
def run(dv,K=(0,11),thr=0.0):
    x=xi.clone()
    with torch.no_grad():
        for k in range(20):
            t=torch.full((len(x),),1-k/20)
            v,A=net.velocity(x,t,c,("blocks.1",),count=False)
            if K[0]<=k<K[1]:
                f=((A['blocks.1']@w+b)>thr).float()[:,None]; v=v+f*dv
            x=x-v/20
    return x.numpy()
A0=torch.tensor(a0)
mask=(torch.abs(c[:,None]-c[None,:])>0.03).float()*1e3
def typ(a):
    return (torch.cdist(torch.tensor(a),A0)+mask).min(1).values.numpy()
for mag in [3,6]:
  for J in range(8):
    th=np.radians(45*J); dv=torch.tensor([np.cos(th),np.sin(th)],dtype=torch.float32)*mag
    a=run(dv); T=tgt(a)
    mv=np.linalg.norm(a-a0,axis=1)>0.3
    ty=typ(a); resc=T0&~T
    print(mag,J,'tgt',round(T.mean(),3),'fall',round(T0.mean()-T.mean(),3),'nontgt moved',round((mv&~T0).mean(),3),'resc atyp',round(((ty>0.25)&resc).sum()/max(resc.sum(),1),2), 'moved atyp', round(((ty>0.25)&mv).mean(),3))

